/* Real raster scenery and transparent purchase cutouts; both game modes share this renderer. */
(function(root){
'use strict';
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function atlas(){return root.ART_MAP||{scenes:{},items:{}};}
function rectArt(info,extra=''){
 if(!info)return '<span class="art-missing" aria-hidden="true"></span>';
 const [x,y,w,h]=info.rect,[fw,fh]=info.size,ratio=w/h,fit=ratio>=1?`width:100%;height:${100/ratio}%`:`height:100%;width:${ratio*100}%`;
 return `<span class="item-art ${extra}" aria-hidden="true"><span class="sprite-crop" style="${fit}"><img src="./${info.file}" alt="" draggable="false" decoding="async" style="width:${fw/w*100}%;left:${-x/w*100}%;top:${-y/h*100}%"></span></span>`;
}
function item(item,extra=''){return rectArt(atlas().items[item.id],extra);}
function backdrop(themeId){const t=atlas().scenes[themeId];if(!t)return '';if(t.single)return `<img class="scene-background" src="./${t.file}" alt="" draggable="false" decoding="async">`;return `<div class="scene-background scene-atlas" style="background-image:url('./${t.file}');background-position:${t.col/3*100}% ${t.row/3*100}%" aria-hidden="true"></div>`;}
function scene(themeId,items,key='',large=false,options={}){
 const t=(root.CATALOG||[]).find(t=>t.id===themeId),ids=items.map(it=>it.id).join(',');
 const cinemaNote=themeId==='sinema'?(items.some(i=>i.id==='sinema-0')&&items.some(i=>i.id==='sinema-4')?'Film başladı · Tropik ada':'Perde + projektör al, film başlasın'):'';
 const counts=new Map();for(const it of items){const g=counts.get(it.id)||{item:it,count:0};g.count++;counts.set(it.id,g);}const quantities=[...counts.values()].filter(g=>g.count>1).map(g=>`<span>${safe(g.item.name)} ×${g.count}</span>`).join('');
 return `<div class="world-scene true-3d ${large?'large-scene':''}" data-scene="${safe(themeId)}" role="group" aria-label="${safe(t?.name||'Oyun alanı')}: ${items.length} ürün, döndürülebilir 3B sahne"><div class="world-3d" data-world-theme="${safe(themeId)}" data-world-owned="${safe(ids)}" data-world-owner="${safe(options.owner||key)}" data-world-state="${safe(JSON.stringify({money:options.money??20,items,placements:options.placements||{}}))}"><span class="world-loading">3B sahne hazırlanıyor…</span><div class="world-camera-tools"><button data-world-zoom="in" aria-label="3B sahneye yakınlaş">+</button><button data-world-zoom="out" aria-label="3B sahneden uzaklaş">−</button><button data-world-reset aria-label="Kamerayı sıfırla">↺</button>${options.editable?'<button class="world-edit-button" data-world-edit aria-pressed="false">✋ Eşyaları düzenle</button><button class="world-turn-button" data-world-turn="-15" aria-label="Seçili eşyayı sola çevir" disabled>↶</button><button class="world-turn-button" data-world-turn="15" aria-label="Seçili eşyayı sağa çevir" disabled>↷</button>':''}</div><span class="world-edit-hint"></span></div>${cinemaNote?`<span class="world-cinema-note">${cinemaNote}</span>`:''}${quantities?`<div class="world-quantities">${quantities}</div>`:''}<span class="world-drag-hint">3B · Sürükle ve döndür</span>${!large?`<button class="scene-expand" aria-label="Sahneyi büyüt" title="Sahneyi büyüt" data-scene-open="${safe(themeId)}" data-owned="${safe(ids)}" data-options="${safe(JSON.stringify(options))}">⛶</button>`:''}</div>`;
}
function category(theme){return `<span class="category-art" aria-hidden="true">${backdrop(theme.id)}</span>`;}
function owned(items){return items.length?`<details class="owned-items"><summary>Alınanları gör (${items.length})</summary><ul>${items.map(it=>`<li>${item(it)}<span>${safe(it.name)}</span><small>${it.points} ürün değeri</small></li>`).join('')}</ul></details>`:'';}
function scoreDetails(s,final=false){const rows=[['Ürün değeri',s.base,25],['Olmazsa olmazlar',s.essentials,25],['Birlikte çalışma',s.functionality,20],['Görsel düzen',s.visual,15],['Çeşitlilik',s.variety,10],['Bütçe ustalığı',s.savings,5]];return `<details class="score-breakdown" ${final?'open':''}><summary>Puan dökümü · 6 ölçüt</summary>${rows.map(([label,value,max])=>`<div class="score-row"><span>${label}</span><b>${value} / ${max}</b><meter min="0" max="${max}" value="${value}" aria-label="${label}"></meter></div>`).join('')}<p class="score-missing">${s.missing.length?'Eksik temel parçalar: '+s.missing.map(safe).join(', '):'Temel parçalar tamamlandı!'}${s.collisions?'<br>Eşyalar üst üste geliyor; düzenleyerek puan kazanabilirsin.':''}</p></details>`;}
function show(themeId,ids,options={}){const t=(root.CATALOG||[]).find(t=>t.id===themeId);if(!t)return;const items=ids.split(',').map(id=>t.items.find(x=>x.id===id)).filter(Boolean);let d=document.querySelector('#scene-viewer');if(!d){d=document.createElement('dialog');d.id='scene-viewer';document.body.append(d);}d.innerHTML=`<button class="close" aria-label="Kapat">×</button><span class="eyebrow">SENİN KURDUĞUN DÜNYA</span><h2>${safe(t.name)}</h2>${scene(themeId,items,'viewer',true,options)}<p class="muted">${items.length} ürün · Sadece kazandığın parçalar sahnende görünür.</p>`;d.querySelector('.close').onclick=()=>d.close();d.onclick=e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}};d.showModal();}
if(typeof document!=='undefined')document.addEventListener('click',e=>{const b=e.target.closest('[data-scene-open]');if(b)show(b.dataset.sceneOpen,b.dataset.owned,JSON.parse(b.dataset.options||'{}'));});
const api={item,scene,category,owned,scoreDetails};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.Visuals=api;
})(typeof window!=='undefined'?window:globalThis);
